def bsd_netinet(tag):
    files = ["tcp.h", "tcp_debug.c", "tcp_debug.h", "tcp_fsm.h", "tcp_input.c", "tcp_output.c", "tcp_seq.h",
             "tcp_subr.c", "tcp_timer.c", "tcp_timer.h", "tcp_usrreq.c", "tcp_var.h", "tcpip.h"]
    return {"artifacts": [{"kind": "url", "extract": False, "filename": f,
                           "url": "https://raw.githubusercontent.com/dspinellis/unix-history-repo/%s/usr/src/sys/netinet/%s" % (tag, f)}
                          for f in files]}


