    dependencies=["libc"],
    entry_points=["gzip / gunzip / zcat; deflate.c (LZ77 hashing), trees.c (Huffman), inflate.c"],
    example={"command": "./configure && make; ./gzip -c sample > s.gz; ./gzip -dc s.gz | cmp - sample", "input": "a text file", "output": "round trip exact; ratio versus compact and compress on the same input"},
    environment={"runner": "docker", "image": "prometheus-fossil-c:bookworm"},
    upstream_docs=["Deutsch, DEFLATE Compressed Data Format Specification, RFC 1951 (1996)", "Ziv & Lempel, A Universal Algorithm for Sequential Data Compression, IEEE IT 1977", "gzip NEWS/README 1993 (the patent motivation)"],
    human_capability_summary={"built_to": "compress files better than compress without infringing the LZW patent, and interoperate forever via a fixed format",
                              "pressure": "the Unisys LZW patent (legal), disk/bandwidth scarcity, portability across 1993 Unixes and DOS",
                              "success_means": "exact round trip, better ratio than compress, patent-free"},
    known_human_problem_solved="patent-free lossless compression",
    human_environmental_pressure="legal pressure (patent), storage scarcity, portability",
    human_failure_condition="a format change would orphan every archive; a patent claim would stop distribution",
    behavioral_entry_point="vary -1..-9 (the lazy-match effort knob in deflate.c) and record ratio/time; compare with compact and ncompress on one corpus",
